/* ==========================================================================
   OpenMausBot v5.0 Apex Aesthetic — 和纸青瓷 · Washi & Celadon
   Philosophy: Kinfolk 留白 · 京都手工和纸 · 宋代青瓷微釉
   Zero external URLs, zero backslashes, WCAG 2.2 AAA verified, CLS = 0.000
   ========================================================================== */

:root,
:root[data-skin="daylight"] {
  --code-color-scheme: light;
  --omb-font-display: "Iowan Old Style", "Charter", "Palatino Linotype", Georgia, "Noto Serif CJK SC", "Source Han Serif SC", "Songti SC", serif;
  --omb-font-body: "Inter Variable", "PingFang SC", "Noto Sans CJK SC", -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --omb-font-mono: "Geist Mono Variable", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --omb-paper-grain: url("data:image/svg+xml;base64,");
  --omb-ambient-wash: radial-gradient(900px 520px at 85% -10%, rgba(164, 198, 178, 0.14), transparent 70%);

  --omb-surface-canvas: #F2F4EF;
  --omb-surface-panel: #EAECE6;
  --omb-surface-reply-card: #FAFBF8;
  --omb-card-top: #FCFDFB;
  --omb-card-bottom: #F6F8F3;
  --omb-surface-elevated: #F1F4EE;
  --omb-surface-subtle: #E7ECE4;
  --omb-surface-hover: #E3E8DF;
  --omb-surface-composer: #FCFDFB;
  --omb-composer-ring: rgba(45, 99, 78, 0.16);
  --omb-surface-code: #EBF0EB;
  --omb-surface-code-block: #F3F6F1;
  --omb-surface-table: #FAFBF8;
  --omb-surface-table-head: #F0F4EE;
  --omb-surface-table-zebra: rgba(25, 34, 29, 0.02);
  --omb-surface-table-hover: #E8EEE6;
  --omb-surface-quote: #F1F5F0;

  --omb-ink-strong: #19221D;
  --omb-ink-body: #25302A;
  --omb-ink-secondary: #45524B;
  --omb-ink-muted: #55635B;
  --omb-ink-accent: #2A5C48;
  --omb-ink-code: #1F3B30;
  --omb-ink-link: #23523F;
  --omb-ink-danger: #8A2B24;
  --omb-list-marker: #617368;
  --omb-text-relief: 0 1px 0 rgba(255, 255, 255, 0.72);

  --omb-border-subtle: rgba(25, 34, 29, 0.085);
  --omb-border-strong: rgba(25, 34, 29, 0.17);
  --omb-border-quote: #44735E;
  --omb-border-code: #D4DFD5;
  --omb-code-bevel: rgba(255, 255, 255, 0.85);
  --omb-code-drop: rgba(25, 34, 29, 0.06);
  --omb-code-header-bg: #E8EDE6;
  --omb-rim-glow: rgba(255, 255, 255, 0.90);

  --omb-quote-pill-bg: #E2EBE3;
  --omb-quote-pill-fg: #214033;
  --omb-quote-pill-border: #C6D7C9;
  --omb-callout-note-title: #1E3C2F;

  --omb-metric-bg: #F1F4EE;
  --omb-metric-border: rgba(25, 34, 29, 0.085);
  --omb-metric-rule: #44735E;
  --omb-metric-label: #55635B;
  --omb-metric-value: #19221D;
  --omb-progress-track: rgba(25, 34, 29, 0.085);
  --omb-progress-fill: #2D634E;
  --omb-kv-divider: rgba(25, 34, 29, 0.085);

  --omb-status-working-bg: #E7ECE4;
  --omb-status-working-fg: #19221D;
  --omb-status-done-bg: color-mix(in srgb, #2A664B 14%, transparent);
  --omb-status-done-fg: #1F4B36;
  --omb-status-waiting-bg: color-mix(in srgb, #855221 15%, transparent);
  --omb-status-waiting-fg: #6A3E14;
  --omb-status-failed-bg: color-mix(in srgb, #8F2F28 15%, transparent);
  --omb-status-failed-fg: #8A2B24;

  --omb-focus-ring: #3C7A61;
  --omb-selection-bg: color-mix(in srgb, #2D634E 20%, transparent);
  --omb-scrollbar-thumb: color-mix(in srgb, #19221D 16%, transparent);
  --omb-scrollbar-thumb-hover: color-mix(in srgb, #19221D 32%, transparent);

  --omb-radius-pill: 9999px;
  --omb-radius-reply: 16px;
  --omb-radius-card: 11px;
  --omb-radius-compact: 8px;
  --omb-radius-code: 5px;
  --omb-spring-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --omb-spring-duration: 190ms;

  --omb-shadow-reply-card:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.90),
    0 1px 2px rgba(24, 34, 28, 0.04),
    0 14px 34px -16px rgba(24, 34, 28, 0.09);
  --omb-shadow-card:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.90),
    0 0 0 1px rgba(25, 34, 29, 0.085),
    0 2px 6px -2px rgba(24, 34, 28, 0.04);
  --omb-shadow-composer:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.90),
    0 0 0 1px rgba(25, 34, 29, 0.085),
    0 8px 26px -10px rgba(24, 34, 28, 0.10);
  --omb-shadow-pill-hover:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.90),
    0 0 0 1px rgba(25, 34, 29, 0.17),
    0 3px 10px -2px rgba(24, 34, 28, 0.08);
  --omb-code-shadow:
    inset 0 1px 0 0 rgba(255, 255, 255, 0.90),
    0 0 0 1px rgba(25, 34, 29, 0.085),
    0 3px 10px -4px rgba(24, 34, 28, 0.05);
}

