/* --------------------------------------------------------------------------
   1. FULL-SHELL MATERIALITY: RAIL, SIDEBAR, HEADER, CHAT GROUND & COMPOSER
   -------------------------------------------------------------------------- */
*, *::before, *::after {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

[data-look="app"],
[data-look="rail"],
[data-look="sidebar"] {
  background-color: var(--omb-surface-panel);
  background-image: var(--omb-paper-grain);
}

[data-look="sidebar"] {
  border-inline-end: 1px solid var(--omb-border-subtle);
}

[data-look="sidebar-bot"],
[data-look="sidebar-thread"] {
  border-radius: var(--omb-radius-compact);
  transition:
    background-color var(--omb-spring-duration) var(--omb-spring-ease),
    box-shadow var(--omb-spring-duration) var(--omb-spring-ease),
    transform 140ms var(--omb-spring-ease);
}

[data-look="sidebar-thread"][aria-current="page"],
[data-look="sidebar-thread"][aria-current="true"] {
  background-color: var(--omb-surface-reply-card);
  box-shadow: var(--omb-shadow-card);
}

[data-look="chat"] {
  background-color: var(--omb-surface-canvas);
  background-image: var(--omb-paper-grain), var(--omb-ambient-wash);
  background-attachment: local;
}

[data-look="chat-header"] {
  background-color: color-mix(in srgb, var(--omb-surface-canvas) 84%, transparent);
  backdrop-filter: blur(14px) saturate(1.1);
  border-bottom: 1px solid var(--omb-border-subtle);
}

[data-look="composer"] {
  background: linear-gradient(180deg, var(--omb-card-top) 0%, var(--omb-surface-composer) 100%);
  border: 0;
  box-shadow: var(--omb-shadow-composer);
  transition:
    box-shadow var(--omb-spring-duration) var(--omb-spring-ease),
    transform var(--omb-spring-duration) var(--omb-spring-ease);
}

[data-look="composer"]:focus-within {
  box-shadow:
    inset 0 1px 0 0 var(--omb-rim-glow),
    0 0 0 1.5px var(--omb-focus-ring),
    0 0 0 5px var(--omb-composer-ring),
    0 12px 32px -12px rgba(0, 0, 0, 0.16);
}

[data-look="user-bubble"] {
  border-radius: var(--omb-radius-reply);
  box-shadow: inset 0 1px 0 0 var(--omb-rim-glow), 0 1px 2px rgba(0, 0, 0, 0.04);
  border: 1px solid var(--omb-border-subtle);
}

.chat-column ::selection {
  background: var(--omb-selection-bg);
  color: var(--omb-ink-strong);
}

/* --------------------------------------------------------------------------
   2. LUMINOUS PAPER / MINERAL REPLY CARDS (0.5px Specular Rim + Soft Wash)
   -------------------------------------------------------------------------- */
[data-look="bot-bubble"].bg-card,
[data-reply-bubble],
[data-conversational-reply] .reply-bubble,
[data-look="message-bot"] [data-look="bot-bubble"]:not([data-chat-bubble="simple"]):not(.bg-card):has(.chat-md):not(:has([data-conversational-reply])) {
  background: linear-gradient(180deg, var(--omb-card-top) 0%, var(--omb-card-bottom) 100%);
  color: var(--omb-ink-body);
  border: 1px solid var(--omb-border-subtle);
  border-radius: var(--omb-radius-reply);
  box-shadow: var(--omb-shadow-reply-card);
  box-sizing: border-box;
}

[data-look="message-bot"] [data-look="bot-bubble"]:not([data-chat-bubble="simple"]):not(.bg-card):has(.chat-md):not(:has([data-conversational-reply])) {
  padding: 24px 28px;
}

.chat-md {
  max-width: 68ch;
  color: var(--omb-ink-body);
  font-family: var(--omb-font-body);
  font-size: 14.75px;
  line-height: 1.74;
  letter-spacing: 0.002em;
  font-variant-numeric: tabular-nums;
}

.chat-wide .chat-md { max-width: 100%; }

.chat-md p {
  color: var(--omb-ink-body);
  margin: 0;
  display: flow-root;
}
.chat-md > * + p { margin-top: 0.9rem; }

/* --------------------------------------------------------------------------
   3. REFINED EDITORIAL TYPOGRAPHY & OPTICAL RELIEF
   -------------------------------------------------------------------------- */
.chat-md :is(h1, h2, h3, h4, h5, h6, .md-heading),
.chat-md > div.font-semibold {
  color: var(--omb-ink-strong);
}

.chat-md :is(h1, .md-heading[class*="text-[20px]"]) {
  font-family: var(--omb-font-display);
  font-size: 24px; font-weight: 750;
  line-height: 1.24;
  font-weight: 700;
  letter-spacing: -0.024em;
  text-shadow: var(--omb-text-relief);
  margin-top: 1.5rem;
  margin-bottom: 0.72rem;
  padding-bottom: 0.62rem;
  border-bottom: 1px solid var(--omb-border-strong);
}

.chat-md :is(h2, .md-heading[class*="text-[17px]"]) {
  font-family: var(--omb-font-display);
  font-size: 19px; font-weight: 700;
  line-height: 1.34;
  font-weight: 650;
  letter-spacing: -0.014em;
  text-shadow: var(--omb-text-relief);
  margin-top: 1.55rem;
  margin-bottom: 0.55rem;
  padding-top: 0.95rem;
  border-top: 1px solid var(--omb-border-subtle);
}

.chat-md :is(h3, h4),
.chat-md > div.font-semibold:not(.md-heading):not([class*="text-[14px]"]) {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  font-family: var(--omb-font-body);
  font-size: 15.5px !important;
  font-weight: 700 !important;
  line-height: 1.35;
  letter-spacing: 0.02em;
  color: var(--omb-ink-accent);
  margin-top: 1.4rem;
  margin-bottom: 0.45rem;
}

.chat-md :is(h3, h4)::before,
.chat-md > div.font-semibold:not(.md-heading):not([class*="text-[14px]"])::before {
  content: "";
  display: inline-block;
  width: 14px;
  height: 1.5px;
  background-color: var(--omb-ink-accent);
  border-radius: 9999px;
  flex-shrink: 0;
}

.chat-md h5,
.chat-md h6,
.chat-md > div.font-semibold[class*="text-[14px]"] {
  font-size: 13.5px; font-weight: 650;
  font-weight: 640;
  letter-spacing: 0.105em;


  color: var(--omb-ink-muted);
  margin-top: 0.9rem;
  margin-bottom: 0.35rem;
}

.chat-md > :first-child {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

/* Lead Deck */
.chat-md > .md-heading[class*="text-[20px]"]:first-child + p,
.chat-md > div.font-semibold[class*="text-[14px]"]:first-child + .md-heading[class*="text-[20px]"] + p {
  font-size: 15.5px;
  line-height: 1.74;
  font-weight: 430;
  color: var(--omb-ink-secondary);
  padding-bottom: 1rem;
  margin-top: 0.55rem;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--omb-border-subtle);
}

/* BFC-Safe Editorial Drop Cap */
.chat-md > .md-heading[class*="text-[20px]"]:first-child + p + p:not(:has(> strong:first-child)):not(:has(> code:first-child))::first-letter,
.chat-md > hr + p:not(:has(> strong:first-child)):not(:has(> code:first-child))::first-letter {
  float: inline-start;
  font-family: var(--omb-font-display);
  font-size: 2.7em;
  font-weight: 700;
  line-height: 0.88;
  padding-inline-end: 0.22em;
  padding-top: 0.05em;
  color: var(--omb-ink-accent);
}

/* Restrained Emphasis (Eliminates Harsh Ink Blobs) */
.chat-md strong, .chat-md b {
  color: var(--omb-ink-strong);
  font-weight: 600;
}

/* --------------------------------------------------------------------------
   4. KEYCAP-BEVEL INLINE CODE & CALM LINKS
   -------------------------------------------------------------------------- */
.chat-md code:not(pre code),
.chat-md .ui-code-chip {
  background-color: var(--omb-surface-code);
  color: var(--omb-ink-code);
  border: 1px solid var(--omb-border-code);
  border-radius: var(--omb-radius-code);
  box-shadow: inset 0 1px 0 var(--omb-code-bevel), 0 1px 1.5px var(--omb-code-drop);
  padding: 0.14em 0.48em;
  font-family: var(--omb-font-mono);
  font-size: 0.84em;
  font-weight: 510;
  line-height: 1.25;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}

.chat-md a:not(.ui-pill):not([data-github-ref]) {
  color: var(--omb-ink-link);
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--omb-ink-link) 34%, transparent);
  text-underline-offset: 3.5px;
  font-weight: 520;
  transition: text-decoration-color var(--omb-spring-duration) var(--omb-spring-ease);
}
.chat-md a:not(.ui-pill):not([data-github-ref]):hover {
  text-decoration-color: var(--omb-ink-link);
}

/* --------------------------------------------------------------------------
   5. SIGNATURE PULL QUOTE, STAT BOX, COLOPHON SPEC & DATA TABLES
   -------------------------------------------------------------------------- */
.chat-md blockquote {
  position: relative;
  margin: 1rem 0 1.2rem;
  padding: 1.05rem 1.35rem 1.05rem 2.85rem;
  border-radius: var(--omb-radius-card);
  border: 1px solid color-mix(in srgb, var(--omb-border-quote) 22%, var(--omb-border-subtle));
  background-color: var(--omb-surface-quote);
  color: var(--omb-ink-body);
  box-shadow:
    inset 3px 0 0 var(--omb-border-quote),
    inset 0 1px 0 0 var(--omb-rim-glow),
    0 2px 8px -4px rgba(0, 0, 0, 0.08);
}

.chat-md blockquote::before {
  content: "“";
  position: absolute;
  top: 0.42rem;
  inset-inline-start: 0.82rem;
  font-family: var(--omb-font-display);
  font-size: 38px;
  line-height: 1;
  font-weight: 700;
  color: var(--omb-border-quote);
  opacity: 0.52;
  pointer-events: none;
}

.chat-md blockquote p {
  font-family: var(--omb-font-display);
  font-size: 15.25px;
  line-height: 1.68;
  margin: 0;
}

.chat-md blockquote p:first-child code {
  border-radius: var(--omb-radius-pill);
  padding: 0.16em 0.68em;
  font-family: var(--omb-font-body);
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.06em;

  background-color: var(--omb-quote-pill-bg);
  color: var(--omb-quote-pill-fg);
  border: 1px solid var(--omb-quote-pill-border);
  box-shadow: none;
  vertical-align: 1px;
}

/* Colophon Fact Sheet */
.chat-md ul:is(:has(> li > strong:first-child), :has(> li > p:first-child > strong:first-child)):not(:has(> li:not(:has(> strong:first-child)):not(:has(> p:first-child > strong:first-child)))) {
  list-style: none;
  padding-inline-start: 0;
  margin: 0.8rem 0 1rem;
  border: 1px solid var(--omb-border-subtle);
  border-radius: var(--omb-radius-card);
  background-color: var(--omb-surface-elevated);
  box-shadow: inset 0 1px 0 0 var(--omb-rim-glow);
  overflow: hidden;
}

.chat-md ul:is(:has(> li > strong:first-child), :has(> li > p:first-child > strong:first-child)):not(:has(> li:not(:has(> strong:first-child)):not(:has(> p:first-child > strong:first-child)))) > li {
  margin-top: 0;
  padding: 0.66rem 1.1rem;
  border-bottom: 1px solid var(--omb-kv-divider);
  transition: background-color 150ms var(--omb-spring-ease);
}
.chat-md ul:is(:has(> li > strong:first-child), :has(> li > p:first-child > strong:first-child)):not(:has(> li:not(:has(> strong:first-child)):not(:has(> p:first-child > strong:first-child)))) > li:hover {
  background-color: var(--omb-surface-subtle);
}
.chat-md ul:is(:has(> li > strong:first-child), :has(> li > p:first-child > strong:first-child)):not(:has(> li:not(:has(> strong:first-child)):not(:has(> p:first-child > strong:first-child)))) > li:last-child {
  border-bottom: 0;
}

/* Code Blocks */
.chat-md .chat-code-block,
[data-look="code-block"].chat-code-block {
  background-color: var(--omb-surface-code-block);
  border: 0;
  border-radius: var(--omb-radius-card);
  box-shadow: var(--omb-code-shadow);
  margin: 0.95rem 0;
  overflow: hidden;
}
.chat-md .chat-code-block > div:first-child:not(:only-child) {
  background-color: var(--omb-code-header-bg);
  border-bottom: 1px solid var(--omb-border-subtle);
  color: var(--omb-ink-secondary);
}
.chat-md pre code,
.chat-md .chat-code-block pre code {
  background: transparent;
  color: inherit;
  border: 0;
  box-shadow: none;
  padding: 0;
}

/* Tables & 1-Row Stat Box */
.chat-table { margin: 1rem 0; }
.chat-table [data-table-card],
.chat-table .rich-table,
.chat-md table {
  background-color: var(--omb-surface-table);
  color: var(--omb-ink-body);
  border: 1px solid var(--omb-border-subtle);
  border-radius: var(--omb-radius-card);
  box-shadow: var(--omb-shadow-card);
}
.chat-table th, .chat-md th {
  color: var(--omb-ink-secondary);
  font-weight: 650;
  font-size: 11px;
  letter-spacing: 0.055em;

  padding: 10px 14px;
  border-bottom: 1px solid var(--omb-border-strong);
  background-color: var(--omb-surface-table-head);
}
.chat-table td, .chat-md td {
  color: var(--omb-ink-body);
  font-size: 13.75px;
  line-height: 1.56;
  padding: 9.5px 14px;
  border-bottom: 1px solid var(--omb-border-subtle);
  font-variant-numeric: tabular-nums;
}
.chat-table tbody tr:last-child td, .chat-md tbody tr:last-child td { border-bottom: 0; }
.chat-table tbody tr:nth-child(even) > td, .chat-md tbody tr:nth-child(even) > td { background-color: var(--omb-surface-table-zebra); }
.chat-table tbody tr:hover > td, .chat-md tbody tr:hover > td { background-color: var(--omb-surface-table-hover); color: var(--omb-ink-strong); }

/* 1-Row Stat Box */
.chat-table:has(tbody > tr:only-child):has(thead > tr > th:nth-child(2)):not(:has(thead > tr > th:nth-child(5))) :is(.rich-table, [data-table-card]) {
  background-color: var(--omb-metric-bg);
  border: 1px solid var(--omb-metric-border);
  border-top: 2px solid var(--omb-metric-rule);
  border-radius: var(--omb-radius-card);
  box-shadow: inset 0 1px 0 0 var(--omb-rim-glow);
}

/* Status Pills & Focus Accessibility */
.chat-column button.ui-pill,
.chat-column a.ui-pill,
.chat-column [data-thread-chip] {
  border-radius: var(--omb-radius-pill);
  background-color: var(--omb-surface-reply-card);
  color: var(--omb-ink-strong);
  box-shadow: var(--omb-shadow-card);
  transition:
    background-color var(--omb-spring-duration) var(--omb-spring-ease),
    box-shadow var(--omb-spring-duration) var(--omb-spring-ease),
    transform 130ms var(--omb-spring-ease);
}
.chat-column button.ui-pill:enabled:hover,
.chat-column a.ui-pill:hover,
.chat-column [data-thread-chip]:enabled:hover {
  background-color: var(--omb-surface-subtle);
  box-shadow: var(--omb-shadow-pill-hover);
  transform: translateY(-0.5px);
}

.chat-column :is(button, a, summary):focus-visible {
  outline: 2px solid var(--omb-focus-ring);
  outline-offset: 2px;
}

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--omb-scrollbar-thumb); border-radius: 9999px; }
::-webkit-scrollbar-thumb:hover { background: var(--omb-scrollbar-thumb-hover); }

@media (prefers-reduced-motion: reduce) {
  .chat-column button.ui-pill, .chat-column a.ui-pill, [data-look="sidebar-thread"], [data-look="composer"] {
    transition: none;
  }
}

